  "Automatically capture future airings with conflict handling and padding.": [
    "Spela automatiskt in kommande sändningar med konflikthantering och tidsmarginal.",
    "Zukünftige Ausstrahlungen automatisch mit Konfliktbehandlung und Vor-/Nachlaufzeit aufnehmen.",
    "Enregistrer automatiquement les prochaines diffusions avec gestion des conflits et marges.",
    "Capturar automáticamente futuras emisiones con gestión de conflictos y márgenes de tiempo.",
    "Capturar automaticamente transmissões futuras com tratamento de conflitos e margens.",
    "Registra automaticamente le messe in onda future con gestione dei conflitti e margini.",
    "Neem toekomstige uitzendingen automatisch op met conflictafhandeling en tijdmarges.",
    "Automatycznie nagrywaj przyszłe emisje z obsługą konfliktów i marginesem czasu.",
    "Çakışma yönetimi ve ek sürelerle gelecekteki yayınları otomatik olarak kaydedin.",
    "Автоматическая запись будущих эфиров с разрешением конфликтов и запасом времени.",
    "Автоматичний запис майбутніх ефірів із вирішенням конфліктів та запасом часу.",
    "التقاط البث المستقبلي تلقائياً مع معالجة التعارضات وهوامش الوقت.",
    "टकराव प्रबंधन और पैडिंग के साथ भविष्य के प्रसारणों को स्वचालित रूप से रिकॉर्ड करें।",
    "自动录制未来的播出，支持冲突处理和前后缓冲时间。",
    "競合処理と前後マージン付きで今後の放送を自動録画します。",
    "충돌 처리 및 여유 시간 설정으로 향후 방송을 자동 녹화합니다.",
    "Rekam tayangan mendatang secara otomatis dengan penanganan konflik dan batas waktu.",
    "Tự động ghi lại các buổi phát sóng sắp tới với xử lý xung đột và thời gian đệm.",
    "Ta opp fremtidige sendinger automatisk med konflikthåndtering og tidsmargin.",
    "Awtomatikong i-record ang mga susunod na palabas na may conflict handling at padding.",
    "Awtomatikong i-rekord ang umaabot nga mga pasundayag uban ang pagdumala sa panagsumpaki ug padding.",
    "Awtomatiko nga i-rekord an tiarabot nga mga pasundayag nga may pagdumara hin conflict ngan padding.",
  ],
  "Retention automatically deletes saved files for this rule. Active playback is kept. Profiles with an age limit record only the guide programme window, without extra padding.":
    [
      "Lagringsregeln raderar automatiskt sparade filer för denna regel. Aktiv uppspelning behålls. Profiler med åldersgräns spelar endast in tablåns programfönster utan extra tidsmarginal.",
      "Die Aufbewahrungsregel löscht gespeicherte Dateien dieser Regel automatisch. Aktive Wiedergaben bleiben erhalten. Profile mit Altersgrenze zeichnen nur das Programmfenster ohne Vor-/Nachlauf auf.",
      "La conservation supprime automatiquement les fichiers enregistrés pour cette règle. La lecture active est préservée. Les profils avec limite d'âge n'enregistrent que le créneau du guide, sans marge.",
      "La retención elimina automáticamente los archivos guardados de esta regla. La reproducción activa se conserva. Los perfiles con límite de edad solo graban la franja de la guía, sin margen extra.",
      "A retenção exclui automaticamente os arquivos salvos desta regra. A reprodução ativa é mantida. Perfis com limite de idade gravam apenas a janela do guia, sem margem extra.",
      "La conservazione elimina automaticamente i file salvati per questa regola. La riproduzione attiva viene mantenuta. I profili con limite di età registrano solo la finestra guida, senza margine extra.",
      "Bewaarbeleid verwijdert automatisch opgeslagen bestanden voor deze regel. Actieve weergave blijft behouden. Profielen met een leeftijdsgrens nemen alleen het gidsvenster op, zonder extra marge.",
      "Retencja automatycznie usuwa zapisane pliki dla tej reguły. Aktywne odtwarzanie jest zachowywane. Profile z limitem wieku nagrywają tylko okno programu z przewodnika, bez dodatkowego marginesu.",
      "Saklama kuralı bu kural için kaydedilen dosyaları otomatik siler. Etkin oynatma korunur. Yaş sınırı olan profiller ek süre olmadan yalnızca rehber aralığını kaydeder.",
      "Правило хранения автоматически удаляет сохраненные файлы. Активное воспроизведение сохраняется. Профили с возрастным ограничением записывают только окно программы без запаса времени.",
      "Правило зберігання автоматично видаляє збережені файли. Активне відтворення зберігається. Профілі з віковим обмеженням записують лише вікно програми без запасу часу.",
      "يحذف الاحتفاظ تلقائياً الملفات المحفوظة لهذه القاعدة. يتم الإبقاء على التشغيل النشط. الملفات الشخصية ذات الحد العمري تسجل نافذة البرنامج فقط دون هامش إضافي.",
      "रिटेंशन इस नियम के लिए सहेजी गई फ़ाइलों को स्वचालित रूप से हटा देता है। सक्रिय प्लेबैक रखा जाता है। आयु सीमा वाली प्रोफ़ाइल बिना अतिरिक्त पैडिंग के केवल गाइड प्रोग्राम विंडो रिकॉर्ड करती हैं।",
      "保留策略会自动删除此规则已保存的文件。正在播放的内容会保留。设有年龄限制的个人资料仅录制节目单时间段，不添加额外缓冲。",
      "保持設定により、このルールの保存済みファイルは自動削除されます。再生中のものは維持されます。年齢制限のあるプロフィールは余백なしで番組枠のみ録画します。",
      "보관 규칙에 따라 저장된 파일이 자동으로 삭제됩니다. 재생 중인 항목은 유지됩니다. 연령 제한이 있는 프로필은 추가 여유 시간 없이 편성표 시간대만 녹화합니다.",
      "Retensi secara otomatis menghapus file tersimpan untuk aturan ini. Pemutaran aktif tetap disimpan. Profil dengan batas usia hanya merekam jendela program panduan tanpa waktu tambahan.",
      "Chính sách lưu trữ sẽ tự động xóa các tệp đã lưu của quy tắc này. Phiên đang phát được giữ lại. Hồ sơ có giới hạn độ tuổi chỉ ghi đúng khung giờ lịch phát sóng, không cộng thêm thời gian đệm.",
      "Oppbevaring sletter automatisk lagrede filer for denne regelen. Aktiv avspilling beholdes. Profiler med aldersgrense tar kun opp programvinduet i guiden, uten ekstra margin.",
      "Awtomatikong binubura ng retention ang mga na-save na file para sa panuntunang ito. Pinananatili ang aktibong pag-play. Ang mga profile na may age limit ay nagre-record lamang ng oras sa guide nang walang dagdag na padding.",
      "Awtomatikong papason sa retention ang na-save nga mga file alang niini nga lagda. Ang aktibong pag-play ipabilin. Ang mga profile nga may age limit magrekord lang sa oras sa giya nga walay dugang padding.",
      "Awtomatiko nga ginpapara han retention an na-save nga mga file para hini nga lagda. An aktibo nga pag-play ginpapabilin. An mga profile nga may age limit nagrerekord la han oras ha giya nga waray dugang nga padding.",
    ],

