      "Genererar en lokal rotcertifikatutfärdare (Root CA) och utfärdar ett servercertifikat giltigt för dina LAN-IP-adresser och värdnamn. Installera rotcertifikatet en gång på din enhet för att få ett grönt hänglås i ditt lokala nätverk utan publik domän.",
