      "Genera una Root CA locale autogestita ed emette un certificato server valido per gli IP e gli hostname della LAN. Installa la Root CA una volta sul dispositivo per ottenere il lucchetto verde sulla LAN senza dominio pubblico.",
      "Genereert een lokaal beheerde Root CA en geeft een servercertificaat uit voor uw LAN-IP-adressen en hostnamen. Installeer de Root CA eenmalig op uw apparaat voor een veilig slotje op uw LAN zonder publiek domein.",
      "Generuje lokalny urząd certyfikacji (Root CA) i wystawia certyfikat serwera dla adresów IP i nazw hostów w sieci LAN. Zainstaluj Root CA raz na urządzeniu, aby uzyskać bezpieczną kłódkę w sieci LAN bez publicznej domeny.",
      "Kendi kendine yönetilen bir Yerel Kök CA oluşturur ve LAN IP adresleriniz ile ana bilgisayar adlarınız için geçerli bir sunucu sertifikası verir. Genel alan adına ihtiyaç duymadan LAN'da güvenli kilit simgesi almak için Kök CA'yı cihazınıza bir kez yükleyin.",
      "Создает локальный корневой ЦС (Root CA) и выпускает сертификат сервера для IP-адресов и имен хостов вашей локальной сети. Установите Root CA один раз на устройство для защищенного соединения в LAN без публичного домена.",
      "Створює локальний кореневий ЦС (Root CA) і випускає сертифікат сервера для IP-адрес та імен хостів вашої локальної мережі. Встановіть Root CA один раз на пристрій для захищеного з'єднання в LAN без публічного домену.",
      "ينشئ سلطة شهادات جذرية محلية ويصدر شهادة خادم صالحة لعناوين IP وأسماء المضيفين في شبكتك المحلية. ثبّت الشهادة الجذرية مرة واحدة على جهازك للحصول على اتصال آمن في الشبكة المحلية دون الحاجة لنطاق عام.",
      "एक स्व-प्रबंधित स्थानीय रूट CA उत्पन्न करता है और आपके LAN IP पतों और होस्टनामों के लिए मान्य सर्वर प्रमाणपत्र जारी करता है। सार्वजनिक डोमेन के बिना अपने LAN पर सुरक्षित पैडलॉक पाने के लिए अपने डिवाइस पर एक बार रूट CA इंस्टॉल करें।",
      "生成自管理的本地根证书颁发机构 (Root CA)，并为您的局域网 IP 地址和主机名签发有效的服务器证书。在设备上安装一次根证书，即可在无公共域名的情况下获得局域网安全连接。",
      "自己管理のローカルルートCAを生成し、LANのIPアドレスとホスト名に有効なサーバー証明書を発行します。端末にルートCAを一度インストールすれば、公開ドメインなしでLAN内のHTTPS接続が可能になります。",
      "자체 관리형 로컬 루트 CA를 생성하고 LAN IP 주소 및 호스트 이름에 유효한 서버 인증서를 발급합니다. 기기에 루트 CA를 한 번 설치하면 공인 도메인 없이도 LAN에서 보안 연결을 사용할 수 있습니다.",
      "Membuat Root CA Lokal mandiri dan menerbitkan sertifikat server yang valid untuk alamat IP dan nama host LAN Anda. Instal Root CA sekali di perangkat Anda untuk mendapatkan gembok aman di LAN tanpa domain publik.",
      "Tạo CA gốc cục bộ tự quản lý và cấp chứng chỉ máy chủ hợp lệ cho địa chỉ IP và tên máy chủ LAN của bạn. Cài đặt CA gốc một lần trên thiết bị để có kết nối an toàn trong mạng LAN mà không cần tên miền công khai.",
      "Genererer en lokal rot-CA og utsteder et serversertifikat som er gyldig for LAN-IP-adressene og vertsnavnene dine. Installer rot-CA-en én gang på enheten for å få sikker tilkobling på LAN uten offentlig domene.",
      "Gumagawa ng Local Root CA at nag-iisyu ng server certificate na valid para sa iyong mga LAN IP address at hostname. I-install nang isang beses ang Root CA sa iyong device para magkaroon ng ligtas na koneksyon sa LAN nang hindi kailangan ng public domain.",
      "Maghimo og Local Root CA ug mo-isyu og server certificate nga balido alang sa imong mga LAN IP address ug hostname. I-install kausa ang Root CA sa imong device aron makakuha og luwas nga koneksyon sa LAN nga walay public domain.",
      "Naghihimo hin Local Root CA ngan nag-iisyu hin server certificate nga balido para han imo mga LAN IP address ngan hostname. I-install hin makausa an Root CA ha imo garamiton basi magkamay-ada talwas nga koneksyon ha LAN nga waray public domain.",
