      "आपका MBL सर्वर कॉन्फ़िगर हो गया है। नीचे क्लिक करने से प्रारंभिक मीडिया स्कैन शुरू होगा और आप होम डैशबोर्ड पर पहुंच जाएंगे।",
      "您的 MBL 服务器已配置完成。点击下方将开始首次媒体扫描并进入主页。",
