      "MBL-serveren din er konfigurert. Klikk nedenfor for å starte den første medieskanningen og gå til startsiden.",
      "Naka-configure na ang iyong MBL server. Ang pag-click sa ibaba ay magsisimula ng unang media scan at magdadala sa iyo sa home dashboard.",
      "Na-configure na ang imong MBL server. Ang pag-klik sa ubos magsugod sa unang media scan ug modala kanimo sa home dashboard.",
