      "क्या आप वाकई इस API टोकन को रद्द करना चाहते हैं? कोई भी जुड़ा हुआ एजेंट तुरंत डिस्कनेक्ट हो जाएगा।",
      "确定要吊销此 API 令牌吗？所有已连接的智能体将立即断开连接。",
      "このAPIトークンを失効させてもよろしいですか？接続中のエージェントは即座に切断されます。",
      "이 API 토큰을 폐기하시겠습니까? 연결된 모든 에이전트가 즉시 연결 해제됩니다.",
      "Apakah Anda yakin ingin mencabut token API ini? Agen yang terhubung akan langsung diputuskan.",
      "Bạn có chắc chắn muốn thu hồi mã API này không? Mọi tác nhân đang kết nối sẽ bị ngắt ngay lập tức.",
      "Er du sikker på at du vil tilbakekalle dette API-tokenet? Enhver tilkoblet agent blir frakoblet umiddelbart.",
