      "Sigurado ka ba nga gusto nimong bawion kini nga API token? Maputol dayon ang koneksyon sa bisan unsang konektado nga agent.",
      "Sigurado ka ba nga karuyag mo bawion ini nga API token? Mapuputol dayon an koneksyon han bisan ano nga nakakonekta nga agent.",
