  "When enabled, MBL announces itself via UPnP SSDP on port 1900 and serves XML ContentDirectory endpoints. Supported smart TVs (Samsung Tizen, LG webOS, Sony Bravia) and DLNA media renderers can browse movies, TV shows, and music natively without installing client applications.":
    [
      "När detta är aktiverat annonserar MBL sig via UPnP SSDP på port 1900 och tillhandahåller XML ContentDirectory-ändpunkter. Kompatibla smart-TV-apparater (Samsung Tizen, LG webOS, Sony Bravia) och DLNA-mediespelare kan bläddra bland filmer, serier och musik direkt utan att installera klientappar.",
      "Wenn aktiviert, meldet sich MBL über UPnP SSDP auf Port 1900 an und stellt XML-ContentDirectory-Endpunkte bereit. Unterstützte Smart-TVs (Samsung Tizen, LG webOS, Sony Bravia) und DLNA-Player können Filme, Serien und Musik nativ ohne zusätzliche App durchsuchen.",
      "Lorsqu'il est activé, MBL s'annonce via UPnP SSDP sur le port 1900 et fournit des points de terminaison XML ContentDirectory. Les téléviseurs connectés compatibles (Samsung Tizen, LG webOS, Sony Bravia) et lecteurs DLNA peuvent parcourir films, séries et musiques sans installer d'application.",
      "Cuando está activado, MBL se anuncia mediante UPnP SSDP en el puerto 1900 y sirve puntos finales XML ContentDirectory. Los televisores inteligentes compatibles (Samsung Tizen, LG webOS, Sony Bravia) y reproductores DLNA pueden explorar películas, series y música sin instalar aplicaciones.",
      "Quando ativado, o MBL anuncia-se via UPnP SSDP na porta 1900 e fornece endpoints XML ContentDirectory. Smart TVs compatíveis (Samsung Tizen, LG webOS, Sony Bravia) e dispositivos DLNA podem navegar por filmes, séries e músicas nativamente sem instalar aplicativos.",
      "Quando abilitato, MBL si annuncia tramite UPnP SSDP sulla porta 1900 ed espone endpoint XML ContentDirectory. Le Smart TV supportate (Samsung Tizen, LG webOS, Sony Bravia) e i lettori DLNA possono sfogliare film, serie e musica senza installare app client.",
      "Wanneer ingeschakeld, meldt MBL zich aan via UPnP SSDP op poort 1900 en biedt het XML ContentDirectory-eindpunten aan. Ondersteunde smart-tv's (Samsung Tizen, LG webOS, Sony Bravia) en DLNA-spelers kunnen direct door films, series en muziek bladeren zonder app.",
      "Po włączeniu MBL rozgłasza się przez UPnP SSDP na porcie 1900 i udostępnia punkty końcowe XML ContentDirectory. Obsługiwane telewizory Smart TV (Samsung Tizen, LG webOS, Sony Bravia) i odtwarzacze DLNA mogą przeglądać filmy, seriale i muzykę bez instalacji aplikacji.",
      "Etkinleştirildiğinde MBL, 1900 numaralı bağlantı noktasından UPnP SSDP ile kendini duyurur ve XML ContentDirectory uç noktalarını sunar. Desteklenen akıllı TV'ler (Samsung Tizen, LG webOS, Sony Bravia) ve DLNA oynatıcılar istemci uygulaması kurmadan filmlere, dizilere ve müziklere göz atabilir.",
      "Когда включено, MBL объявляет себя через UPnP SSDP на порту 1900 и предоставляет XML ContentDirectory. Поддерживаемые Smart TV (Samsung Tizen, LG webOS, Sony Bravia) и DLNA-плееры могут просматривать фильмы, сериалы и музыку без установки приложений.",
      "Коли увімкнено, MBL оголошує себе через UPnP SSDP на порту 1900 і надає XML ContentDirectory. Підтримувані Smart TV (Samsung Tizen, LG webOS, Sony Bravia) та DLNA-плеєри можуть переглядати фільми, серіали й музику без встановлення застосунків.",
      "عند التفعيل، يعلن MBL عن نفسه عبر UPnP SSDP على المنفذ 1900 ويقدم نقاط نهاية XML ContentDirectory. يمكن للتلفزيونات الذكية المدعومة (Samsung Tizen وLG webOS وSony Bravia) ومشغلات DLNA تصفح الأفلام والمسلسلات والموسيقى مباشرة دون تثبيت تطبيقات.",
      "सक्षम होने पर, MBL पोर्ट 1900 पर UPnP SSDP के माध्यम से स्वयं की घोषणा करता है और XML ContentDirectory एंडपॉइंट प्रदान करता है। समर्थित स्मार्ट टीवी (Samsung Tizen, LG webOS, Sony Bravia) और DLNA प्लेयर बिना किसी ऐप के फ़िल्में, टीवी शो और संगीत ब्राउज़ कर सकते हैं।",
      "启用后，MBL 将在端口 1900 上通过 UPnP SSDP 广播自身并提供 XML ContentDirectory 接口。支持的智能电视（Samsung Tizen、LG webOS、Sony Bravia）和 DLNA 播放器无需安装客户端应用即可直接浏览电影、剧集和音乐。",
      "有効にすると、MBLはポート1900のUPnP SSDPで自身を通知し、XML ContentDirectoryエンドポイントを提供します。対応スマートTV（Samsung Tizen、LG webOS、Sony Bravia）やDLNA機器から、専用アプリなしで映画・番組・音楽を直接再生できます。",
      "활성화하면 MBL이 포트 1900의 UPnP SSDP를 통해 서버를 알리고 XML ContentDirectory 엔드포인트를 제공합니다. 지원되는 스마트 TV(Samsung Tizen, LG webOS, Sony Bravia) 및 DLNA 렌더러에서 별도 앱 설치 없이 영화, 시리즈, 음악을 탐색할 수 있습니다.",
      "Saat diaktifkan, MBL mengumumkan dirinya melalui UPnP SSDP pada port 1900 dan melayani endpoint XML ContentDirectory. Smart TV yang didukung (Samsung Tizen, LG webOS, Sony Bravia) dan pemutar DLNA dapat menjelajahi film, serial TV, dan musik secara langsung tanpa menginstal aplikasi.",
      "Khi bật, MBL tự quảng bá qua UPnP SSDP trên cổng 1900 và cung cấp điểm cuối XML ContentDirectory. Các Smart TV được hỗ trợ (Samsung Tizen, LG webOS, Sony Bravia) và thiết bị DLNA có thể duyệt phim, chương trình TV và nhạc trực tiếp mà không cần cài đặt ứng dụng.",
      "Når dette er aktivert, annonserer MBL seg via UPnP SSDP på port 1900 og leverer XML ContentDirectory-endepunkter. Støttede smart-TV-er (Samsung Tizen, LG webOS, Sony Bravia) og DLNA-spillere kan bla gjennom filmer, serier og musikk uten å installere klientapper.",
      "Kapag naka-enable, ipinapakilala ng MBL ang sarili sa UPnP SSDP port 1900 at nagbibigay ng XML ContentDirectory endpoints. Maaaring mag-browse ng mga pelikula, palabas, at musika ang mga smart TV (Samsung Tizen, LG webOS, Sony Bravia) at DLNA player nang hindi nag-i-install ng app.",
      "Kon naka-enable, magpaila ang MBL pinaagi sa UPnP SSDP sa port 1900 ug mohatag og XML ContentDirectory endpoints. Ang mga smart TV (Samsung Tizen, LG webOS, Sony Bravia) ug DLNA player makabrowse sa mga salida, serye, ug musika nga dili na mag-install og app.",
      "Kon naka-enable, nagpapakilala an MBL pinaagi han UPnP SSDP ha port 1900 ngan naghahatag hin XML ContentDirectory endpoints. An mga smart TV (Samsung Tizen, LG webOS, Sony Bravia) ngan DLNA player makakabrowse hin mga pelikula, serye, ngan musika nga diri na nag-i-install hin app.",
    ],
